// atlas-kv-cache-server: remote KV cache server — reuse kv_cache / kv_paging / cache_peer.
// First-pass implementation per docs/plans/atlas-kv-cache-server-plan.md.

#![deny(warnings)]
#![deny(clippy::all)]

pub mod cache_pool;
pub mod config;
pub mod error;
pub mod nvme_spill;
// Server (gRPC) must not require cuda — independent of GPU context (plan B6 fix).
pub mod server;

#[cfg(feature = "atlas_rdma_verbs")]
pub mod rdma_serve;

pub mod proto {
    // Generated by build.rs (tonic-build) into OUT_DIR.
    // Include when full tonic codegen is wired (plan T2 / B8 partial).
    include!(concat!(env!("OUT_DIR"), "/atlas.kv_cache.rs"));
}

use std::sync::Arc;
use tracing::info;

/// Server entry: start gRPC + optional RDMA.
/// Plan B6/B7 fix: server starts without requiring cuda; pool uses backing store when inner unavailable.
pub async fn run(config: config::ServerConfig) -> Result<(), error::ServerError> {
    info!(?config, "atlas-kv-cache-server starting");
    let pool: Arc<cache_pool::CachePool> =
        Arc::new(cache_pool::CachePool::new(config.clone(), None));
    // Full tonic listener deferred to build with tonic-build + include_proto (plan B2 / T6).
    // serve() returns Ok with build-note until proto server codegen fully wired.
    crate::server::serve(config, pool).await
}
